import { Pinecone } from '@pinecone-database/pinecone'; import OpenAI from 'openai'; const pinecone = new Pinecone({ apiKey: process.env.PINECONE_API_KEY }); const openai = new OpenAI({ apiKey: process.env.OPENAI_API_KEY }); // 1. Index documents (one-time setup) async function indexDocuments(documents) { const index = pinecone.index('knowledge-base'); for (const doc of documents) { // Generate embedding const embedding = await openai.embeddings.create({ model: 'text-embedding-3-small', input: doc.text }); // Store in Pinecone await index.upsert([ { id: doc.id, values: embedding.data[0].embedding, metadata: { text: doc.text, title: doc.title } } ]); } } // 2. RAG query async function answerQuestion(question) { const index = pinecone.index('knowledge-base'); // Step 1: Retrieve relevant documents const queryEmbedding = await openai.embeddings.create({ model: 'text-embedding-3-small', input: question }); const searchResults = await index.query({ vector: queryEmbedding.data[0].embedding, topK: 5, includeMetadata: true }); // Step 2: Build context from retrieved docs const context = searchResults.matches .map(match => match.metadata.text) .join('

'); // Step 3: Generate answer using context const response = await openai.chat.completions.create({ model: 'gpt-5.3', messages: [ { role: 'system', content: 'Answer questions based on the provided context. If the answer is not in the context, say so.' }, { role: 'user', content: `Context:
${context}

Question: ${question}` } ] }); return { answer: response.choices[0].message.content, sources: searchResults.matches.map(m => ({ title: m.metadata.title, similarity: m.score })) }; } // Usage const result = await answerQuestion('How do I reset my password?'); console.log(result.answer); console.log('Sources:', result.sources);

